from __future__ import annotations

import logging

import re

from dataclasses import dataclass

from typing import Any, Optional

from scp.meta.severity import Severity

logger = logging.getLogger('scp.knowledge.antibodies')

@dataclass
class AntibodyResult:
    """Kết quả 1 antibody check."""
    antibody_name: str
    domain: str
    passed: bool = True
    severity: str = Severity.INFO
    confidence: float = 0.5
    details: str = ''

    def to_dict(self) -> dict[str, Any]:
        return {'antibody': self.antibody_name, 'domain': self.domain, 'passed': self.passed, 'severity': self.severity, 'confidence': self.confidence, 'details': self.details}

